function h($v){ return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8'); }
function sb($cfg, $path){ $ch=curl_init(rtrim($cfg['supabase_url'],'/').$path); curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['apikey: '.$cfg['service_role_key'],'Authorization: Bearer '.$cfg['service_role_key']]]); $resp=curl_exec($ch); $code=curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch); return $code>=200&&$code<300 ? (json_decode($resp,true)?:[]) : []; }
$slug = preg_replace('/[^a-z0-9\-]/','', strtolower((string)($_GET['slug']??'')));
$post = $slug ? (sb($cfg, '/rest/v1/webping_posts?select=*&slug=eq.'.urlencode($slug).'&status=eq.published&limit=1')[0] ?? null) : null;
